-- Private bucket for the lesson PDFs and their internal sources, and the Storage RLS that lets an owner read ONLY their
-- own PDFs. Written only when Supabase Storage exists (the plain-Postgres test database has no `storage` schema).
--
-- Object paths are {owner}/{lesson}/{revision}/{attempt}/{document}.{pdf|tex}, generated by the server. Browsers get no
-- write access at all: the worker writes with the secret key, which bypasses RLS. `.tex` files are never readable by
-- users (decision D-31), even their own: the policy admits the pdf extension only.
DO $$
BEGIN
  IF to_regnamespace('storage') IS NULL THEN
    RAISE NOTICE 'storage schema not present; skipping the lesson-artifacts bucket';
    RETURN;
  END IF;

  INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  VALUES ('lesson-artifacts', 'lesson-artifacts', false, 26214400, ARRAY['application/pdf', 'application/x-tex', 'text/x-tex', 'text/plain'])
  ON CONFLICT (id) DO UPDATE
    SET public = false, file_size_limit = EXCLUDED.file_size_limit, allowed_mime_types = EXCLUDED.allowed_mime_types;

  DROP POLICY IF EXISTS lesson_artifacts_owner_reads_pdf ON storage.objects;
  CREATE POLICY lesson_artifacts_owner_reads_pdf ON storage.objects
    FOR SELECT TO authenticated
    USING (
      bucket_id = 'lesson-artifacts'
      AND (storage.foldername(name))[1] = (SELECT auth.uid())::text
      AND storage.extension(name) = 'pdf'
    );
END
$$;
